function remember(saved,month,periods){const cache=confirmed();if(periods)cache.periods=periods;if(saved){const old=cache.records[saved.month];if(!old||old.revision<=saved.revision){delete cache.records[saved.month];cache.records[saved.month]=saved}if(!cache.periods.some(p=>p.month===saved.month))cache.periods.push({month:saved.month,revision:saved.revision})}else if(month)delete cache.records[month];for(const old of Object.keys(cache.records).slice(0,-12))delete cache.records[old];cache.time=Date.now();try{localStorage.setItem(CONFIRMED_KEY,JSON.stringify(cache))}catch(_){} }
